package ozl.startup.tests;
import java.nio.file.*;import java.util.*;import zombie.ui.*;import zombie.gameStates.*;import zombie.core.*;import ozl.startup.*;
public final class WorkshopScrollbarTest {
 public static void main(String[] args)throws Exception{Path game=Path.of(args[0]);for(int count:new int[]{2,12}){NativeLuaFixture f=new NativeLuaFixture(game,640,480);f.function("getText",(c,n)->c.push(((String)c.get(0)).contains("ItemState_")?"正在下载验证项目 Long near full width status":c.get(0)));WorkshopScaleTest.prepare(f,game,count);UIElement list=WorkshopDownloadTest.widget(f,"listbox");var scroll=NativeLuaFixture.element((se.krka.kahlua.vm.KahluaTable)list.getTable().rawget("vscroll"));ArrayList<UIElement.Text> texts=new ArrayList<>();ArrayList<UIElement.Stencil> stencils=new ArrayList<>();ArrayList<String> order=new ArrayList<>();UIElement.textDrawing=t->{texts.add(t);if(t.element()==list)order.add("row");};UIElement.stencilDrawing=s->{stencils.add(s);order.add(s.enabled()?"set":"clear");};UIElement.drawing=d->{f.draws.add(d);if(d.element==scroll)order.add("scroll");};MainScreenState.instance.render();boolean visible=count==12;double width=WorkshopDownloadTest.number(list,"width"),edge=width-8-(visible?17:0),stencilRight=visible?width-13:width-1;UIElement.Stencil clip=stencils.stream().filter(s->s.element()==list&&s.enabled()).findFirst().orElseThrow();if(Math.abs(clip.x()+clip.w()-stencilRight)>.01)throw new AssertionError("actual list stencil right boundary");
  for(var d:f.draws)if(d.element==list&&d.h>4&&d.h<=40&&d.a==1&&((d.r==.24&&d.g==.19)||(d.r==.12&&d.g==.32)))if(d.x+d.w>edge+.01)throw new AssertionError("badge loses original scrollbar reserve: right="+(d.x+d.w)+", edge="+edge);
  boolean ellipsis=false;for(var t:texts)if(t.element()==list&&t.x()>16){double right=t.x()+TextManager.instance.MeasureStringX(UIFont.Small,t.text());if(right>edge+.01)throw new AssertionError("near-full status clipped by scrollbar");ellipsis|=t.text().endsWith("…");}if(!ellipsis)throw new AssertionError("full-width status must be measured and ellipsized");if(order.indexOf("set")>order.indexOf("row")||order.indexOf("clear")<order.lastIndexOf("row"))throw new AssertionError("native stencil must surround all-row traversal");if(visible&&order.indexOf("scroll")<order.indexOf("clear"))throw new AssertionError("native scrollbar draws after row stencil clear");if(visible&&order.indexOf("scroll")<0)throw new AssertionError("real scrollbar render missing");SpriteRenderer.instance.recycle();System.out.println("PASS scrollbar "+(visible?"visible":"hidden")+" content edge="+edge+", stencil edge="+stencilRight);}}
}
